<template>
  <main class="grading-page">
    <header class="grading-heading"><div><span class="overline">教学评阅工作台</span><h1>批阅中心</h1><p>按题、按班筛选作答，对照评分细则连续批阅。</p></div><div class="heading-actions"><router-link v-if="user.isAdmin" to="/admin/questions">题库工作台 ↗</router-link><el-button @click="download" :loading="exporting">导出筛选成绩</el-button></div></header>
    <div class="grading-summary"><span>全部提交 <strong>{{ overview.attempts??'—' }}</strong></span><span>待评阅 <strong>{{ overview.pending??'—' }}</strong></span><span>已完成 <strong>{{ overview.graded??'—' }}</strong></span><small>Ctrl / ⌘ + Enter 保存并下一份 · Alt + ↑ / ↓ 切换</small></div>
    <section class="grading-filters"><el-input v-model="filters.search" placeholder="姓名、学号或题目" clearable @keyup.enter="filterChanged" @clear="filterChanged" aria-label="搜索作答"/><el-select v-model="filters.topic" clearable placeholder="全部专题" @change="filterChanged" aria-label="专题筛选"><el-option v-for="t in metadata.topics" :key="t.id" :label="t.title" :value="t.id"/></el-select><el-select v-model="filters.question_id" clearable filterable placeholder="全部题目" @change="filterChanged" aria-label="题目筛选"><el-option v-for="q in metadata.questions" :key="q.id" :label="q.title" :value="q.id"/></el-select><el-select v-model="filters.class_name" clearable placeholder="全部班级" @change="filterChanged" aria-label="班级筛选"><el-option v-for="c in metadata.classes" :key="c" :label="c" :value="c"/></el-select><el-select v-model="filters.status" @change="filterChanged" aria-label="评阅状态"><el-option label="待评阅" value="pending"/><el-option label="已评阅" value="graded"/><el-option label="全部作答" value="all"/></el-select><el-button @click="filterChanged">筛选</el-button><el-checkbox v-model="filters.latest_only" @change="filterChanged">每人每题仅最新一次</el-checkbox></section>
    <p v-if="notice" class="notice" role="alert">{{ notice }}</p>
    <div class="grading-grid">
      <aside class="queue-panel" v-loading="queueLoading"><header><strong>作答队列</strong><span>{{ total }} 份</span></header><el-empty v-if="!queue.length" description="当前条件下没有作答" :image-size="65"/>
        <button v-for="a in queue" :key="a.id" :class="['queue-item',{active:current?.id===a.id}]" :disabled="saving||detailLoading" @click="selectAttempt(a.id)"><div><strong>{{ a.student_name }}</strong><span>{{ a.status==='graded'?'已评阅':'待评' }}</span></div><small>{{ a.student_number||'未填学号' }} · {{ a.class_name||'未填班级' }}</small><p><Notation :text="a.question_title"/></p><small>{{ formatDate(a.created_at) }}</small></button>
        <div class="queue-pages"><button :disabled="page<=1||saving" @click="changePage(-1)">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><button :disabled="page*20>=total||saving" @click="changePage(1)">下一页</button></div>
      </aside>
      <section class="grading-detail" v-loading="detailLoading">
        <el-empty v-if="!current" description="选择一份学生作答开始评阅"/>
        <template v-else>
          <header class="submission-heading"><div><span class="student-pill">{{ current.student_name }} · {{ current.student_number||'未填学号' }}</span><h2><Notation :text="current.question_title"/></h2><p>{{ current.class_name||'未填班级' }} · {{ formatDate(current.created_at) }} · 作答 #{{ current.id }}</p></div><div class="submission-nav"><button :disabled="saving||!canPrevious" @click="navigate(-1)">↑ 上一份</button><button :disabled="saving||!canNext" @click="navigate(1)">下一份 ↓</button></div></header>
          <details class="question-context"><summary>查看提交时的题干、条件与完整站场</summary><p><Notation :text="current.question.prompt"/></p><ul><li v-for="c in current.question.conditions" :key="c"><Notation :text="c"/></li></ul><ClassicStationCanvas :answer="emptyDiagram" reference-mode/><p class="muted">依据：{{ current.question.source_section }}</p></details>
          <div class="grade-totals"><article><span>客观项</span><strong>{{ current.result.automatic_score }}<small> / {{ current.result.automatic_max }}</small></strong></article><article><span>人工项预填</span><strong>{{ enteredManual }}<small> / {{ current.result.manual_max }}</small></strong></article><article><span>{{ incomplete?'尚有未评分项':'预览合计' }}</span><strong v-if="incomplete">{{ incomplete }}<small> 栏待评</small></strong><strong v-else>{{ previewTotal }}<small> / {{ current.result.total_max }}</small></strong></article></div>
          <details class="automatic-feedback"><summary>客观项自动核对结果（{{ current.result.automatic_score }}/{{ current.result.automatic_max }}）</summary><article v-for="f in automaticFields" :key="f.id"><strong><Notation :text="f.label"/> · {{ f.points }}/{{ f.max_points }} 分</strong><p>学生填写：<Notation :text="answerText(current.answers[f.id])"/></p><p v-for="error in f.errors" :key="error"><Notation :text="error"/></p><p>参考填写：<Notation :text="answerText(f.expected)" :runs="f.expected_runs"/></p><p class="muted"><Notation :text="f.explanation"/></p></article></details>
          <fieldset class="manual-fields" :disabled="saving||detailLoading">
            <article v-for="(f,i) in manualFields" :key="f.id" class="manual-field"><header><h3><span>{{ i+1 }}</span><Notation :text="f.label"/></h3><small>{{ f.points }} 分</small></header><div class="answer-block"><span>学生作答</span><p><Notation :text="answerText(current.answers[f.id])"/></p></div>
              <details v-if="f.explanation" class="manual-reference"><summary>参考答案、解析与资料缺口</summary><p><Notation :text="f.explanation"/></p></details>
              <div class="rubric-block"><div class="rubric-heading"><strong>{{ f.rubric?.length?'分项评分细则':'评分参考要点' }}</strong><div><button @click="quick(f,0)">零分</button><button @click="quick(f,.5)">半分</button><button @click="quick(f,1)">满分</button></div></div>
                <template v-if="f.rubric?.length"><div v-for="r in f.rubric" :key="r.id" class="rubric-grade"><span>{{ r.label }}</span><div class="rubric-controls"><button :class="{selected:form.rubric_scores[f.id][r.id]===0}" @click="form.rubric_scores[f.id][r.id]=0">0</button><button :class="{selected:form.rubric_scores[f.id][r.id]===r.points}" @click="form.rubric_scores[f.id][r.id]=r.points">{{ r.points }}</button><input v-model.number="form.rubric_scores[f.id][r.id]" type="number" min="0" :max="r.points" step="0.5" :aria-label="`${f.label}-${r.label}-得分`"><small>/ {{ r.points }}</small></div></div></template>
                <ul v-else><li v-for="point in f.criteria" :key="point">{{ point }}</li></ul>
                <label class="field-score">本栏得分<input v-model.number="form.scores[f.id]" type="number" min="0" :max="f.points" step="0.5" :readonly="Boolean(f.rubric?.length)" :aria-label="`${f.label}-总分`"><span>/ {{ f.points }}</span><small v-if="f.rubric?.length">按细则自动合计</small></label>
              </div>
              <label class="field-comment">本栏反馈（可选）<textarea v-model="form.field_comments[f.id]" rows="2" maxlength="2000" placeholder="指出具体错误和改进方法。" :aria-label="`${f.label}-反馈`"/></label>
            </article>
          </fieldset>
          <section v-if="manualFields.length" class="overall-feedback"><div class="feedback-heading"><h3>总体评语</h3><span>{{ draftStatus }}</span></div><div class="snippet-library"><span>常用评语</span><button v-for="(text,i) in defaults" :key="i" @click="appendComment(text)" :disabled="saving||detailLoading">{{ text }}</button><span v-for="snippet in snippets" :key="snippet.id" class="saved-snippet"><button :title="snippet.text" @click="appendComment(snippet.text)" :disabled="saving||detailLoading">{{ snippet.text }}</button><button class="remove-snippet" @click="removeSnippet(snippet.id)" :disabled="saving||detailLoading" aria-label="移除此常用评语">×</button></span></div><textarea v-model="form.comment" rows="4" maxlength="6000" placeholder="总结本次作答表现，给出下一步改进建议。" aria-label="总体评语" :disabled="saving||detailLoading"/><button class="save-snippet" @click="saveSnippet" :disabled="!form.comment.trim()||saving">＋ 将当前评语存入常用评语</button><label v-if="current.review" class="regrade-reason">更正原因（修改已评阅成绩时必填）<textarea v-model="form.reason" rows="2" maxlength="1000" aria-label="更正原因" :disabled="saving||detailLoading"/></label></section>
          <div v-if="manualFields.length" class="grading-toolbar"><span>{{ current.review?'此作答已评阅，再次提交将记录成绩更正。':'发布评分后，学生可在“我的作答”查看成绩与评语。' }}</span><div><el-button @click="persistDraft" :disabled="saving||detailLoading">保存评分草稿</el-button><el-button @click="grade(false)" :loading="saving">{{ current.review?'保存更正':'保存评分' }}</el-button><el-button type="primary" @click="grade(true)" :disabled="saving||detailLoading">保存并下一份 →</el-button></div></div>
          <details class="audit-history"><summary>评分历史与更正记录（{{ current.audit.length }}）</summary><el-empty v-if="!current.audit.length" :image-size="55" description="尚无人工评分记录"/><article v-for="a in current.audit" :key="a.id"><strong>{{ a.reviewer }} · {{ formatDate(a.created_at) }}</strong><p>{{ a.reason }}</p><p>总分：{{ a.before.result.total_score??'待评' }} → {{ a.after.result.total_score }}</p><p>{{ a.after.review.comment }}</p></article></details>
        </template>
      </section>
    </div>
  </main>
</template>

<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/store/user'
import ClassicStationCanvas from '@/components/ClassicExam/ClassicStationCanvas.vue'
import Notation from '@/components/RailwayNotation.vue'
import {getManagementMetadata,getManagementOverview,listReviews,getReview,saveReviewDraft,submitGrade,exportGrades,getFeedbackSnippets,addFeedbackSnippet,deleteFeedbackSnippet} from '@/api/management'
const user=useUserStore(),metadata=ref({topics:[],classes:[],questions:[]}),overview=ref({}),queue=ref([]),current=ref(null),total=ref(0),page=ref(1),queueLoading=ref(false),detailLoading=ref(false),saving=ref(false),exporting=ref(false),notice=ref(''),snippets=ref([]),draftStatus=ref(''),dirty=ref(false)
const filters=reactive({search:'',topic:null,question_id:null,class_name:'',status:'pending',latest_only:true}),form=ref({scores:{},rubric_scores:{},field_comments:{},comment:'',reason:'',etag:''})
const defaults=['请区分实际占用、检测显示与进路锁闭。','请补充条件、现象和原因之间的对应关系。','结论清楚，请补充实验记录或资料依据。']
const emptyDiagram={route_buttons:[],switches:{},hostile_signals:[],track_sections:[]}
const manualFields=computed(()=>current.value?.question.fields.filter(f=>f.kind==='essay')||[]),automaticFields=computed(()=>current.value?.result.feedback.filter(f=>f.status!=='pending_review')||[])
const numeric=v=>typeof v==='number'&&Number.isFinite(v)
const enteredManual=computed(()=>Math.round(Object.values(form.value.scores).reduce((s,n)=>s+(numeric(n)?n:0),0)*100)/100)
const incomplete=computed(()=>manualFields.value.filter(f=>!numeric(form.value.scores[f.id])).length)
const previewTotal=computed(()=>Math.round(((current.value?.result.automatic_score||0)+enteredManual.value)*100)/100)
const index=computed(()=>queue.value.findIndex(a=>a.id===current.value?.id)),canPrevious=computed(()=>index.value>0||page.value>1),canNext=computed(()=>index.value>=0&&(index.value<queue.value.length-1||page.value*20<total.value))
let initializing=false,loadSerial=0,detailSerial=0,timer=null,draftChain=Promise.resolve()
const clone=v=>JSON.parse(JSON.stringify(v))
function params(){return {...filters,topic:filters.topic||undefined,question_id:filters.question_id||undefined,class_name:filters.class_name||undefined}}
function formatDate(v){return v?new Date(v.endsWith('Z')?v:v+'Z').toLocaleString('zh-CN'):'—'}
function answerText(v){return Array.isArray(v)?v.join(' → '):String(v??'')}
function message(e,fallback){return typeof e.response?.data?.detail==='string'?e.response.data.detail:fallback}
function localKey(id){return `srtp_grading_${user.user?.id}_${id}`}
watch(()=>form.value.rubric_scores,()=>{if(initializing)return;for(const f of manualFields.value){if(!f.rubric?.length)continue;const values=f.rubric.map(r=>form.value.rubric_scores[f.id]?.[r.id]);form.value.scores[f.id]=values.every(numeric)?Math.round(values.reduce((a,b)=>a+b,0)*100)/100:''}},{deep:true,flush:'sync'})
watch(form,()=>{if(initializing||!current.value)return;dirty.value=true;draftStatus.value='正在保留评分草稿…';try{localStorage.setItem(localKey(current.value.id),JSON.stringify(form.value))}catch{};clearTimeout(timer);timer=setTimeout(()=>persistDraft(false),1000)},{deep:true,flush:'sync'})
async function persistDraft(showToast=false){
  clearTimeout(timer);if(!current.value||!dirty.value)return true
  const id=current.value.id,payload=clone(form.value),signature=JSON.stringify(payload)
  // Serialize writes from this page so older requests cannot replace newer drafts.
  const operation=draftChain.catch(()=>{}).then(()=>saveReviewDraft(id,payload));draftChain=operation
  try{await operation;if(current.value?.id===id&&JSON.stringify(form.value)===signature){dirty.value=false;draftStatus.value='评分草稿已保存，尚未发布。'}if(showToast===true)ElMessage.success('评分草稿已保存');return true}catch(e){if(current.value?.id===id)draftStatus.value='后台草稿保存失败，本机内容仍保留。';if(showToast===true)notice.value=message(e,'草稿保存失败，请重试。');return false}
}
function adopt(data){
  initializing=true;current.value=data
  let draft=data.draft;try{const local=JSON.parse(localStorage.getItem(localKey(data.id)));if(local?.etag===data.etag)draft=local}catch{}
  const validDraft=draft?.etag===data.etag?draft:null
  const review=data.review||{}
  form.value={etag:data.etag,scores:Object.fromEntries(data.question.fields.filter(f=>f.kind==='essay').map(f=>[f.id,review.scores?.[f.id]??''])),rubric_scores:Object.fromEntries(data.question.fields.filter(f=>f.kind==='essay'&&f.rubric?.length).map(f=>[f.id,Object.fromEntries(f.rubric.map(r=>[r.id,review.rubric_scores?.[f.id]?.[r.id]??'']))])),field_comments:Object.fromEntries(data.question.fields.filter(f=>f.kind==='essay').map(f=>[f.id,review.field_comments?.[f.id]||''])),comment:review.comment||'',reason:''}
  if(validDraft)form.value={...form.value,...validDraft}
  dirty.value=false;draftStatus.value=validDraft?'已恢复尚未发布的评分草稿。':data.review?'已载入发布成绩。':'评分草稿自动保存，提交后学生可见。'
  if(draft&&!validDraft)notice.value='成绩已更新，旧评分草稿未套用，请依据当前成绩评阅。'
  initializing=false
}
async function selectAttempt(id){if(saving.value)return;if(dirty.value&&!(await persistDraft(true)))return;const token=++detailSerial;detailLoading.value=true;notice.value='';try{const data=await getReview(id);if(token===detailSerial)adopt(data)}catch(e){notice.value=message(e,'作答读取失败。')}finally{if(token===detailSerial)detailLoading.value=false}}
async function loadQueue(selectFirst=false){const token=++loadSerial;queueLoading.value=true;try{const data=await listReviews({...params(),page:page.value});if(token!==loadSerial)return;queue.value=data.items;total.value=data.total;if(page.value>1&&!data.items.length){page.value--;return loadQueue(selectFirst)}if(selectFirst){if(data.items.length)await selectAttempt(data.items[0].id);else{current.value=null;dirty.value=false}}}finally{if(token===loadSerial)queueLoading.value=false}}
async function filterChanged(){if(saving.value)return;if(dirty.value&&!(await persistDraft(true)))return;page.value=1;await loadQueue(true)}
async function changePage(d){if(dirty.value&&!(await persistDraft(true)))return;page.value+=d;await loadQueue(true)}
async function navigate(d){if(saving.value)return;const next=queue.value[index.value+d];if(next)await selectAttempt(next.id);else if(d>0&&canNext.value)await changePage(1);else if(d<0&&canPrevious.value){if(dirty.value&&!(await persistDraft(true)))return;page.value--;await loadQueue();if(queue.value.length)await selectAttempt(queue.value.at(-1).id)}}
function quick(f,ratio){if(f.rubric?.length){for(const r of f.rubric)form.value.rubric_scores[f.id][r.id]=Math.round(r.points*ratio*100)/100}else form.value.scores[f.id]=Math.round(f.points*ratio*100)/100}
function appendComment(text){form.value.comment+=(form.value.comment.trim()?'\n':'')+text}
async function saveSnippet(){const text=form.value.comment.trim();if(!text)return;try{snippets.value.unshift(await addFeedbackSnippet(text));ElMessage.success('已加入你的常用评语')}catch(e){notice.value=message(e,'保存常用评语失败。')}}
async function removeSnippet(id){try{await ElMessageBox.confirm('移除此常用评语？已发送的评语不受影响。','管理评语',{confirmButtonText:'移除',cancelButtonText:'取消'})}catch{return}await deleteFeedbackSnippet(id);snippets.value=snippets.value.filter(s=>s.id!==id)}
async function grade(next){
  if(saving.value||!current.value)return
  if(incomplete.value||!form.value.comment.trim()){notice.value='请完成每个论述栏评分，并填写总体评语。';return}
  if(current.value.review&&!form.value.reason.trim()){notice.value='请填写本次成绩更正原因。';return}
  const id=current.value.id,oldIndex=index.value,payload=clone(form.value)
  saving.value=true;notice.value='';clearTimeout(timer)
  try{await draftChain.catch(()=>{});const response=await submitGrade(id,payload);dirty.value=false;localStorage.removeItem(localKey(id));adopt(response);draftStatus.value='成绩及反馈已发布。';await loadQueue();overview.value=await getManagementOverview();ElMessage.success('评分已保存');if(next){saving.value=false;const remaining=queue.value.filter(a=>a.id!==id);const target=remaining[Math.min(Math.max(oldIndex,0),remaining.length-1)];if(target)await selectAttempt(target.id);else notice.value='当前筛选队列已批阅完成。'}}catch(e){notice.value=message(e,'评分保存失败，草稿仍保留。')}finally{saving.value=false}
}
async function download(){exporting.value=true;try{const blob=await exportGrades(params());const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='实验专题成绩.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}finally{exporting.value=false}}
function keydown(e){if(e.repeat)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();grade(true)}else if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();navigate(e.key==='ArrowUp'?-1:1)}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>!dirty.value||await persistDraft(true))
onMounted(async()=>{const [meta,stats,library]=await Promise.all([getManagementMetadata(),getManagementOverview(),getFeedbackSnippets()]);metadata.value=meta;overview.value=stats;snippets.value=library;await loadQueue(true);window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{clearTimeout(timer);window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload)})
</script>

<style scoped>
